compares:[
 {h:'<span>17/06/2026</span> — أمر الإحضار الساري 3859',
  a:'نص طلب الإحضار (بيانات الطلب على بوابة محاكم دبي — لا ورقة PDF لنص الطلب): «ميسور الحال وراتبه يتعدى 50 ألف درهم (مرفق ما يفيد)».',
  b:'المرفق الوحيد (وصفه في البوابة: «كشف حساب يبين راتبه») كشف صادر في 16/01/2025 — قبل الطلب بسبعة عشر شهراً — ورصيده الختامي 3.25 درهم، ومعه شهادة إيجار انتهت 09/08/2025. لا شيء فيه عن راتب في 2026.',be:['cbi','ejari'],
  c:'صدر أمر الإحضار في اليوم نفسه.',ce:'o3859'},
 {h:'<span>08/12/2025</span> — أمر الإحضار 5619',
  a:'«ثبت أن راتبه 50 ألف درهم (مرفق ما يثبت)، وعقد إيجار منزله 175,000 درهم (مرفق ما يثبت)… وحسابه البنكي الذي يتعدى 150 ألف درهم (مرفق ما يثبت)» — النص في الطلب 247 (PDF) الذي أحاله القاضي إلى نظام الموانع، ثم في طلب الإحضار.',ae:'r247',
  b:'المرفق «ما يفيد يسار المنفذ ضده»: الكشف نفسه برصيد 3.25 درهم — لا رصيد فيه يقارب 150 ألفاً — وشهادة إيجار انتهت قبل الطلب بأربعة أشهر.',be:['cbi','ejari'],
  c:'صدر أمر الإحضار في اليوم نفسه.',ce:'o5619'},
 {h:'<span>24/10/2025</span> — أمر الإحضار 4908',
  a:'نص طلب الإحضار (بيانات الطلب على بوابة محاكم دبي — لا ورقة PDF لنص الطلب): «يقتضي راتب يفوق الـ50 ألف درهم ويمتلك إقامة ذهبية».',
  b:'المرفق الوحيد بطلب الإحضار: صورة هوية المنفذ ضده. لا شهادة راتب ولا كشف ولا ما يخص «إقامة ذهبية» (25-10-24 أحمد هوية المنفذ 270977-2025-1.pdf — ملف القضية 870/أوامر الإحضار - المرفقات).',
  c:'صدر أمر الإحضار في اليوم نفسه.',ce:'o4908'},
 {h:'<span>2024–2025</span> — أربعة أوامر إحضار «لعدم سداد مبلغ 0»',
  a:'طلبات إحضار بعبارات: «تحايل»، «ثبت يساره»، «راتبه 50 ألف» — بلا مبلغ محدد وبلا مرفق يثبت اليسار.',ae:['r101','r129'],
  b:'وكيلتها نفسها كتبت بعد يومين من أمر 28/12/2024: الأمر صدر «لعدم سداد مبلغ 0» وطلبت «تحديد المبلغ المطالب به».',be:'r134',
  c:'أوامر الإحضار في 23/10/2024 و28/12/2024 و09/02/2025 و08/12/2025 نصّها: «نأمر بإحضار منفذ ضده… لعدم سداد مبلغ 0 أو لأي سبب آخر».',ce:'o5619'},
 {h:'<span>22/01/2026</span> — التأمين الصحي: الطلب 281',
  a:'«التأمين الصحي… حتى الآن لم يتم توفيره ولا يكترث لصحة المحضونين بتاتاً… تحت طائلة الضبط والإحضار».',ae:'r281',
  b:'الطلب بلا أي مرفق. فاتورتاها هي (08/01/2026) عليهما وثيقة تأمين والتأمين دفع 459.16 من 509.16. وبطاقتا آدم وسليم ساريتان من 10/01/2026 — قبل الطلب بـ12 يوماً. وقولها أمام المحكمة في 04/04/2024: «الأبناء لديهم تأمين صحي… وتم عمله من قبل المدعى عليه».',be:['sess','med','s_ins1'],
  c:'قرار 10/02/2026: «المنفذ ضده لتنفيذ السند التنفيذي بشأن استخراج بطاقة تأمين صحي لأولاده سليم وآدم وتسليمها لطالبة التنفيذ».',ce:'r281'},
 {h:'<span>08/12/2025</span> — البنوك: الطلب 251 «تم الحجز على 13,270.3»',
  a:'«تم الحجز على مبلغ 13270.3 درهم إلا أن البنك لم يحول سوى مبلغ 789.18… إعادة المخاطبة لتحويل المبالغ كاملة».',ae:'r251',
  b:'رد البنك المرفق بالطلب نفسه يقول العكس: «إجمالي المبلغ / المبالغ المجمدة: 0»، والرقم 13270.3 مكتوب تحت «الرصيد الحالي» لا تحت مبلغ محجوز.',be:'adib',
  c:'«نصرح وفق مضمون الطلب».',ce:'r251'},
 {h:'<span>09/05/2025</span> — الحجز بـ80,702.04 بعد السداد الكامل',
  a:'«توقيع الحجز… في حدود مبلغ وقدره 80702.04 درهم».',ae:'r187',
  b:'الطلب بلا أي مرفق. ومذكرة المحكمة 07/05/2025: المستحق 39,412.44 — وسُدد كاملاً في 08/05/2025 (مذكرة 15/05: «مسدد بالزيادة»).',be:'m0515',
  c:'صدر قرار الحجز في اليوم نفسه (09/05/2025)، ثم أُلغي في 10/05/2025.',ce:['r187','r188']},
 {h:'<span>22/01/2026</span> — منع السفر «للخشية من هروبه»',
  a:'طلب منع السفر 38172/2026 (بيانات الطلب على بوابة محاكم دبي — لا ورقة PDF لنص الطلب): «متعنت عن تجديد إقامات المحضونين… وعدم تمكينهم من توفير تأمين صحي… ولعلم طالبة الأمر بسفره وتهديده بالسفر… وتخشى هروبه».',ae:'p21',
  b:'الطلب 21 في العريضة (05/01/2026) الذي طلب منع السفر «خوفاً من هروبه» بلا أي مرفق. ونص الأمر نفسه: «أفادت طالبة التنفيذ بوجود الخشية من هروبه». وهوية سليم مجددة منذ 07/04/2025، وبطاقتا التأمين ساريتان من 10/01/2026. وفي ملف التنفيذ 870 أمام القاضي نفسه: قرار 14/09/2024 «رفض المنع لعدم ثبوت الخشية من هروبه»، وسداد 66,420 درهماً في 20/01/2026.',be:['r75','crec'],
  c:'أمر منع السفر 22/01/2026 — وفي اليوم التالي مذكرة المحكمة: «مسدد بالزيادة 9.74».',ce:['ban','m0123']},
 {h:'<span>19/01/2026</span> — غرامة 3,000 على «لم يلتحقوا بصفوفهم»',
  a:'الطلب 21 في العريضة 2790 (05/01/2026): «المحضونين لم يتمكنوا من الالتحاق بصفوفهم حتى تاريخه».',ae:'p21',
  b:'الطلب بلا مرفق. وإيصالا المدرسة 04/01/2026 باسم الطالبين (Y10 وY03)، وإقرار وكيلتها في الطلب 256 (06/01/2026) بسداده 18,400 للمدرسة — أمام القاضي نفسه في ملف التنفيذ 870.',be:['srec','r256'],
  c:'«يغرم المعروض ضده 3000 درهم إضافية للغرامة السابقة لامتناعه عن التنفيذ».',ce:'p21'},
],
